-- 00271 — Constats-types PSSI-ES pour l'ensemble des contrôles (couverture complète).
-- Généré depuis 00140 (source de vérité des 213 contrôles). Un constat-type « minor_nc »
-- par contrôle : constat = référence à l'exigence, recommandation = texte de l'exigence,
-- risque = formulation par domaine. Garde d'idempotence : n'insère pas si le contrôle a
-- déjà un constat-type plateforme « minor_nc » (ex. starters 00270).

insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
select 'platform', c.id, 'minor_nc', t.descr, ARRAY[t.risk], ARRAY[t.reco]
from (values
  ('REG 6-1', 'Non-conformité à l’exigence REG 6-1 « Inventaire précis des actifs ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Procéder à un inventaire précis des actifs de l''organisme afin de les identifier et le mettre à jour.'),
  ('REG 5-1', 'Non-conformité à l’exigence REG 5-1 « Exigences de sécurité à l''acquisition de nouveaux systèmes ».', 'Manquement à une exigence PSSI-ES (Acquisition et développement des SI) — introduction de vulnérabilités dès l’acquisition ou le développement.', 'Mettre en œuvre l’exigence : Il faut prendre en compte les exigences liées au contrôle d''accès, à la sensibilisation des utilisateurs, à la protection de la confidentialité, de la disponibilité et de l''intégrité de l''information, et à la journalisation, la surveillance et la détection de fuite de données.'),
  ('REG 20-1', 'Non-conformité à l’exigence REG 20-1 « Procédures d''installation et configuration documentées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Des procédures bien documentées doivent être établies pour l''installation et la configuration des systèmes.'),
  ('REG 2-1', 'Non-conformité à l’exigence REG 2-1 « Information des agents sur leurs responsabilités SSI ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : À l''embauche, les agents doivent être informés, au préalable, de leur rôle sur la sécurité de l''information et leurs responsabilités dans l''application effective de la politique de sécurité de l''organisme.'),
  ('REG 17-1', 'Non-conformité à l’exigence REG 17-1 « Mesures de sécurité pour les applications métier ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Spécifier les mesures de sécurité pour les applications métier.'),
  ('REG 8-1', 'Non-conformité à l’exigence REG 8-1 « Zones sécurisées identifiées et définies ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les centres de données, les salles des serveurs, les salles d''exploitation, les salles de commutation, les installations de stockage, les salles de service et les salles des équipements réseau doivent être considérées comme des zones sécurisées.'),
  ('REG 29-1', 'Non-conformité à l’exigence REG 29-1 « Procédures de surveillance, détection, analyse et signalement ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Mettre en œuvre des procédures de surveillance, de détection, d''analyse et de signalement des événements et des incidents concernant les activités des réseaux.'),
  ('REG 28-1', 'Non-conformité à l’exigence REG 28-1 « Externalisation basée sur une analyse de risques ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Toute opération d''externalisation s''appuie sur une analyse de risques préalable, de façon à formaliser des objectifs de sécurité et définir des mesures adaptées. L''ensemble des objectifs de sécurité ainsi formalisés permet de définir une cible de sécurité servant de cadre au contrat établi avec le prestataire.'),
  ('REG 1-1', 'Non-conformité à l’exigence REG 1-1 « Formation des AQSSI au Comité de sécurité ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : Les membres du Comité de sécurité agissant en tant qu''AQSSI doivent au préalable subir une sensibilisation et une formation en matière de sécurité des SI, en vue d''accomplir avec efficience les missions qui leur sont confiées.'),
  ('REG 30-1', 'Non-conformité à l’exigence REG 30-1 « Audits SSI réguliers pour vérifier l''atteinte des objectifs ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Il faut effectuer des audits pour s''assurer que les objectifs de sécurité sont atteints et que les politiques de sécurité sont conformes aux normes de sécurité en vigueur. Les rapports d''audit doivent être communiqués à la Commission nationale de cryptologie.'),
  ('REG 7-1', 'Non-conformité à l’exigence REG 7-1 « Politique de sécurité applicable aux fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en place une politique de sécurité applicable aux différents fournisseurs (logistique, finance, informatique, …).'),
  ('REG 8-2', 'Non-conformité à l’exigence REG 8-2 « Contrôle d''accès par autorisation écrite ou badge ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : L''accès à ces zones ne doit être permis qu''au personnel muni d''une autorisation écrite ou d''un badge délivré par le responsable désigné.'),
  ('REG 17-2', 'Non-conformité à l’exigence REG 17-2 « Principe du besoin d''en connaître ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Appliquer le principe du besoin d''en connaître : « Nul ne peut, du seul fait de son grade ou son titre, avoir accès aux informations sensibles s''il n''est pas habilité et s''il n''a pas besoin d''en connaître pour réaliser ses tâches ».'),
  ('REG 1-2', 'Non-conformité à l’exigence REG 1-2 « Formation confiée aux organismes compétents ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : La sensibilisation et la formation doivent être confiées aux organismes compétents, notamment l''ADIE, le STCC-SSI, l''ARTP ou tout autre organisme public ou privé dont les compétences sont avérées.'),
  ('REG 30-2', 'Non-conformité à l’exigence REG 30-2 « Compétence des auditeurs SSI ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Les auditeurs des systèmes d''information de l''entité doivent être compétents.'),
  ('REG 2-2', 'Non-conformité à l’exigence REG 2-2 « Engagement de comportement responsable ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Les agents doivent s''engager à avoir un comportement responsable et qui ne représente aucun risque pour la sécurité de l''information.'),
  ('REG 5-2', 'Non-conformité à l’exigence REG 5-2 « Développement sécurisé des logiciels ».', 'Manquement à une exigence PSSI-ES (Acquisition et développement des SI) — introduction de vulnérabilités dès l’acquisition ou le développement.', 'Mettre en œuvre l’exigence : Sécuriser les locaux utilisés pour le développement de logiciels et appliquer les recommandations relatives à la sécurité du langage choisi, notamment dans les phases de conception, du choix des référentiels, du contrôle des versions et de la correction du code source.'),
  ('REG 6-2', 'Non-conformité à l’exigence REG 6-2 « Affectation des actifs à des responsables ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Affecter les actifs à des responsables désignés et qui sont chargés d''assurer leur sécurité (classification, protection et contrôle d''accès).'),
  ('REG 7-2', 'Non-conformité à l’exigence REG 7-2 « Procédures de surveillance de la conformité fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en œuvre des procédures permettant de surveiller la conformité aux exigences de sécurité de l''information pour chaque fournisseur.'),
  ('REG 29-2', 'Non-conformité à l’exigence REG 29-2 « Structure d''alerte et de réaction rapide avec point focal ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Mettre en place, au sein de l''entité, une structure d''alerte et de réaction rapide à tout incident relatif à la sécurité des systèmes d''information, composée d''un personnel qualifié avec un point focal qui sert d''interlocuteur entre l''entité et les autres centres de gestion des incidents.'),
  ('REG 28-2', 'Non-conformité à l’exigence REG 28-2 « Hébergement national obligatoire des données sensibles ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : L''hébergement des données sensibles de l''Administration sur le territoire national est obligatoire, sauf accord du HFD, et dérogation dûment motivée et précisée dans la décision d''homologation.'),
  ('REG 20-2', 'Non-conformité à l’exigence REG 20-2 « Procédures de redémarrage et récupération documentées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Une procédure bien documentée de redémarrage et de récupération de chaque système, en cas de défaillance, doit être définie et appliquée.'),
  ('REG 6-3', 'Non-conformité à l’exigence REG 6-3 « Règles d''utilisation correcte des actifs ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Identifier, documenter, et mettre en œuvre des règles d''utilisation correcte de l''information, des actifs associés à l''information et des moyens de traitement de l''information.'),
  ('REG 17-3', 'Non-conformité à l’exigence REG 17-3 « Principe du besoin d''utiliser ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Appliquer le principe du besoin d''utiliser : « Nul ne peut, du seul fait de son grade ou son titre, avoir accès aux moyens de traitement des informations sensibles, s''il n''est pas habilité et s''il n''a pas besoin de les utiliser pour accomplir son travail ».'),
  ('REG 28-3', 'Non-conformité à l’exigence REG 28-3 « Sensibilisation aux risques du télétravail et des terminaux mobiles ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Sensibiliser les utilisateurs aux problèmes liés à la sécurité des systèmes d''information, notamment les risques encourus dans le cadre du télétravail et de l''utilisation des terminaux mobiles dans les lieux publics, les aéroports, les chambres d''hôtel, les salles de congrès, de réunions, de conférences et dans d''autres zones non sécurisées.'),
  ('REG 5-3', 'Non-conformité à l’exigence REG 5-3 « Application des normes et standards de développement sécurisé ».', 'Manquement à une exigence PSSI-ES (Acquisition et développement des SI) — introduction de vulnérabilités dès l’acquisition ou le développement.', 'Mettre en œuvre l’exigence : Appliquer les normes et standards en vigueur sur le développement sécurisé d''applications (ISO, IEC, ...).'),
  ('REG 8-3', 'Non-conformité à l’exigence REG 8-3 « Registre d''accès aux zones sécurisées ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Un registre d''accès doit être tenu à l''entrée de chaque zone sécurisée. Il doit contenir l''identité, le but, la signature, l''heure d''entrée et de sortie de toute personne accédant au site.'),
  ('REG 29-3', 'Non-conformité à l’exigence REG 29-3 « Remontée rapide et coordination des incidents ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Les structures d''alerte et de réaction rapide doivent remonter tout incident lié à la sécurité des systèmes d''information de l''entité et les signaler aux organismes compétents (ADIE, STCC-SSI, ARTP…). Les actions à mener doivent être coordonnées.'),
  ('REG 30-3', 'Non-conformité à l’exigence REG 30-3 « Rapports d''audit avec recommandations au HFD et à la Commission ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Les auditeurs doivent établir des rapports d''audit à l''attention notamment du Haut Fonctionnaire de Défense (HFD) accompagnés de recommandations à mettre en œuvre pour corriger les éventuelles anomalies. En cas de violation flagrante des procédures, des sanctions doivent être prises conformément aux textes en vigueur. Les rapports d''audit doivent être communiqués à la Commission nationale de cryptologie qui fera un rapport de synthèse à l''attention du Président de la République.'),
  ('REG 1-3', 'Non-conformité à l’exigence REG 1-3 « Sensibilisation permanente des ASSI ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : Les Agents de Sécurité des Systèmes d''Information (ASSI) doivent, en permanence, être sensibilisés sur leurs responsabilités et formés au même titre que les AQSSI.'),
  ('REG 2-3', 'Non-conformité à l’exigence REG 2-3 « Habilitation et charte de confidentialité ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Les agents qui ont accès à l''information sensible et aux systèmes d''information doivent faire, au préalable, l''objet d''enquêtes de sécurité et de moralité, être habilités et signer une charte de confidentialité et de non-divulgation. Il doit en être de même pour les prestataires.'),
  ('REG 20-3', 'Non-conformité à l’exigence REG 20-3 « Procédures de sauvegarde et maintenance documentées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Une procédure bien documentée de sauvegarde et de maintenance, pour chaque système, doit être définie et appliquée.'),
  ('REG 7-3', 'Non-conformité à l’exigence REG 7-3 « Programme de sensibilisation des fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en place un programme de sensibilisation du personnel en contact avec les fournisseurs sur les règles de sécurité applicables à ces derniers ainsi que sur le niveau d''accès aux systèmes d''information.'),
  ('REG 5-4', 'Non-conformité à l’exigence REG 5-4 « Externalisation du développement ».', 'Manquement à une exigence PSSI-ES (Acquisition et développement des SI) — introduction de vulnérabilités dès l’acquisition ou le développement.', 'Mettre en œuvre l’exigence : En cas d''externalisation du développement de logiciels, le maître d''œuvre doit se conformer aux exigences de sécurité citées supra mais aussi considérer les problèmes relatifs aux licences d''utilisation, à la qualité du développement et aux tests de sécurité à réaliser pendant le développement.'),
  ('REG 30-4', 'Non-conformité à l’exigence REG 30-4 « Application des mesures de conformité proposées ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Toutes les structures auditées doivent appliquer les mesures proposées et faire leurs rapports de conformité.'),
  ('REG 20-4', 'Non-conformité à l’exigence REG 20-4 « Contacts support technique disponibles et à jour ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les contacts du support technique doivent être disponibles et tenus à jour, pour faire face notamment aux difficultés d''exploitation.'),
  ('REG 6-4', 'Non-conformité à l’exigence REG 6-4 « Restitution des actifs en fin de contrat/mission ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Veiller à la restitution effective des actifs dans leur totalité, en cas de fin de contrat ou de mission.'),
  ('REG 7-4', 'Non-conformité à l’exigence REG 7-4 « Charte de sécurité signée par les fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en place une charte de sécurité signée par les différentes parties qui doivent s''engager à en respecter scrupuleusement les clauses.'),
  ('REG 1-4', 'Non-conformité à l’exigence REG 1-4 « Note d''organisation fixant la répartition des responsabilités ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : Une note d''organisation doit fixer la répartition des responsabilités au sein de l''entité ; cette note doit être proposée par le RSSI et validée par l''autorité de l''entité.'),
  ('REG 29-4', 'Non-conformité à l’exigence REG 29-4 « Système de redondance pour garantir la disponibilité ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Un système de redondance des moyens de traitement de l''information doit être mis en place en vue d''en garantir la disponibilité.'),
  ('REG 8-4', 'Non-conformité à l’exigence REG 8-4 « Agent de sécurité à l''entrée des sites sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Un agent de sécurité doit être placé à l''entrée de chaque site sensible, chargé de : interdiction d''accès au personnel non autorisé, inscription au registre d''accès, contrôle des bagages, gestion des alarmes et appels d''urgence.'),
  ('REG 28-4', 'Non-conformité à l’exigence REG 28-4 « Protection physique des appareils mobiles contre le vol ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Les appareils mobiles doivent être physiquement protégés contre le vol, en cas de déplacement des utilisateurs. Ils doivent être mis sous clé et dotés de systèmes de verrouillage spéciaux.'),
  ('REG 17-4', 'Non-conformité à l’exigence REG 17-4 « Cloisonnement des rôles pour le contrôle des accès ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Effectuer un cloisonnement des rôles pour le contrôle des accès.'),
  ('REG 2-4', 'Non-conformité à l’exigence REG 2-4 « Information sur les sanctions en cas de violation ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Les agents qui ont accès à l''information sensible doivent être informés de leurs responsabilités en matière de sécurité et être prévenus des sanctions prévues en cas de violation de la politique de sécurité de l''organisme.'),
  ('REG 30-5', 'Non-conformité à l’exigence REG 30-5 « Conformité légale et réglementaire ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Il faut se conformer aux lois et règlements concernant l''utilisation, l''importation, l''exportation et la fourniture des moyens et des prestations de cryptologie, les droits de propriété intellectuelle, la protection de la vie privée et des données à caractère personnel, et, partant, la cybersécurité.'),
  ('REG 20-5', 'Non-conformité à l’exigence REG 20-5 « Normes de sécurité des équipements documentées et suivies ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les normes de sécurité de l''équipement doivent être documentées et suivies.'),
  ('REG 7-5', 'Non-conformité à l’exigence REG 7-5 « Rappel des exigences légales et réglementaires ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Rappeler les exigences légales et réglementaires sur les lois relatives à la protection des données à caractère personnel, sur les droits d''auteur et sur la propriété intellectuelle, et veiller à leur respect.'),
  ('REG 2-5', 'Non-conformité à l’exigence REG 2-5 « Signalement obligatoire des incidents ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Tout personnel utilisateur d''un système d''information, qui constate un événement susceptible de dénoter un incident de sécurité informatique, doit le signaler, sans délai, au service compétent.'),
  ('REG 6-5', 'Non-conformité à l’exigence REG 6-5 « Classification des informations selon leur sensibilité ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Procéder à une classification des informations suivant leur sensibilité et leur caractère sensible (cf. Instruction présidentielle n° 0303/PR du 16 juillet 2003).'),
  ('REG 29-5', 'Non-conformité à l’exigence REG 29-5 « Revue périodique du plan de continuité d''activité ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Il faut revoir régulièrement le plan de continuité d''activités pour prendre en compte les changements intervenus dans le système d''information afin d''en maintenir la validité et l''efficacité.'),
  ('REG 8-5', 'Non-conformité à l’exigence REG 8-5 « Fermeture et verrouillage hors heures de service ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les zones sécurisées doivent être fermées en dehors des heures de service. Toutes les fenêtres, portes, et issues de secours doivent être verrouillées. Tous les conduits (climatisation, élévateurs…) doivent être munis de grilles métalliques.'),
  ('REG 17-5', 'Non-conformité à l’exigence REG 17-5 « Mise à jour régulière des droits d''accès ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Mettre à jour régulièrement les droits d''accès attribués aux utilisateurs.'),
  ('REG 1-5', 'Non-conformité à l’exigence REG 1-5 « Planification des actions de mise en place de la PSSI-ES ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : Le Responsable de la sécurité des systèmes d''information planifie les actions de mise en place de la PSSI-ES.'),
  ('REG 28-5', 'Non-conformité à l’exigence REG 28-5 « Politique de contrôle d''accès mobile et protection anti-malware ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Mettre en place une politique de contrôle d''accès, protéger les appareils mobiles contre les logiciels malveillants, effectuer des sauvegardes et éviter l''installation d''applications non approuvées.'),
  ('REG 2-6', 'Non-conformité à l’exigence REG 2-6 « Protection des données à caractère personnel ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Les données à caractère personnel doivent être protégées et traitées conformément aux dispositions de la loi 2008-12 du 25 janvier 2008 portant sur la protection des données à caractère personnel.'),
  ('REG 1-6', 'Non-conformité à l’exigence REG 1-6 « Formalisation et tenue à jour des documents validés ».', 'Manquement à une exigence PSSI-ES (Organisation de la sécurité des SI) — défaut de gouvernance et de pilotage de la sécurité des SI.', 'Mettre en œuvre l’exigence : Le Responsable de la sécurité des systèmes d''information doit formaliser et tenir à jour les documents validés par le Chef de département (sur son périmètre).'),
  ('REG 30-6', 'Non-conformité à l’exigence REG 30-6 « Publication et mise à jour des normes de sécurité par la Commission ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : La Commission nationale de cryptologie publie et met à jour régulièrement les normes de sécurité auxquelles doivent se conformer tous les systèmes d''information de l''État du Sénégal.'),
  ('REG 8-6', 'Non-conformité à l’exigence REG 8-6 « Révocation immédiate des droits d''accès ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les droits d''accès doivent être immédiatement révoqués en cas de départ à la retraite de l''agent, de démission, de suspension, de mutation ou de congé de longue durée.'),
  ('REG 6-6', 'Non-conformité à l’exigence REG 6-6 « Protection des supports d''information amovibles ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Les informations stockées dans des supports amovibles doivent être protégées contre toute divulgation, modification ou destruction.'),
  ('REG 7-6', 'Non-conformité à l’exigence REG 7-6 « Point focal sécurité pour les fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en place un point focal qui sera chargé de communiquer sur les questions de sécurité avec les fournisseurs.'),
  ('REG 20-6', 'Non-conformité à l’exigence REG 20-6 « Interdiction d''installer des logiciels sans rapport avec l''activité ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : L''installation de logiciels n''ayant aucun rapport avec les activités de l''entité doit être prohibée.'),
  ('REG 29-6', 'Non-conformité à l’exigence REG 29-6 « Test périodique du plan de continuité ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Il faut tester périodiquement le plan afin de s''assurer de sa fiabilité.'),
  ('REG 17-6', 'Non-conformité à l’exigence REG 17-6 « Revue des privilèges en cas de changement de poste ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Revoir régulièrement les privilèges et les droits d''accès en cas de changement de poste de travail.'),
  ('REG 28-6', 'Non-conformité à l’exigence REG 28-6 « Chiffrement labellisé pour les données mobiles ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Empêcher la compromission et la divulgation des informations sensibles stockées et traitées par les appareils mobiles en utilisant les algorithmes de chiffrement labellisés par la Commission nationale de cryptologie.'),
  ('REG 30-7', 'Non-conformité à l’exigence REG 30-7 « Rapports complets communiqués aux autorités ».', 'Manquement à une exigence PSSI-ES (Audit et conformité) — non-conformité réglementaire non détectée faute d’audit.', 'Mettre en œuvre l’exigence : Des rapports complets doivent être communiqués aux autorités compétentes des entités de telle sorte que des mesures puissent être prises lors de la planification de futurs projets sur la base de l''expérience actuelle.'),
  ('REG 3-1', 'Non-conformité à l’exigence REG 3-1 « Gestion des accès lors des mouvements de personnel ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : En cas de mouvement de personnel, de changement de personnel, ou en cas de rupture de contrat ou de fin de contrat, tous les aspects relatifs à la sécurité de l''information doivent être pris en compte : gestion et révocation des comptes et des droits d''accès, gestion du contrôle d''accès aux locaux, gestion des équipements mobiles, gestion du principe d''habilitation et des principes du besoin d''en connaître et d''utiliser.'),
  ('REG 6-7', 'Non-conformité à l’exigence REG 6-7 « Effacement sécurisé des matériels mis au rebut ».', 'Manquement à une exigence PSSI-ES (Gestion des actifs) — actifs non maîtrisés, non protégés ou non imputables.', 'Mettre en œuvre l’exigence : Pour les matériels qui doivent être mis au rebut, il faut procéder à un effacement sécurisé des données qui y sont stockées tel que défini par l''Instruction présidentielle n° 0303/PR du 16 juillet 2003.'),
  ('REG 7-7', 'Non-conformité à l’exigence REG 7-7 « Prise en compte des sous-traitants ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Tous les intervenants doivent être pris en compte, notamment les sous-traitants qui travaillent pour le compte de fournisseurs.'),
  ('REG 8-7', 'Non-conformité à l’exigence REG 8-7 « Sauvegarde des enregistrements d''accès ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les enregistrements d''accès doivent être régulièrement sauvegardés et conservés pendant une période déterminée.'),
  ('REG 18-1', 'Non-conformité à l’exigence REG 18-1 « Mécanisme de contrôle d''accès aux fonctions applicatives ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Un mécanisme permettant de contrôler l''accès aux fonctions d''application système doit être mis en place.'),
  ('REG 20-7', 'Non-conformité à l’exigence REG 20-7 « Interdiction d''utiliser des logiciels non autorisés ou sans licence ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : L''utilisation de logiciels non autorisés, et sans une licence authentique, doit être strictement interdite.'),
  ('REG 28-7', 'Non-conformité à l’exigence REG 28-7 « Usage professionnel exclusif des appareils mobiles ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Veiller à ce que les appareils mobiles de l''organisme ne soient utilisés que pour des usages professionnels.'),
  ('REG 29-7', 'Non-conformité à l’exigence REG 29-7 « Formation des utilisateurs aux actions en cas de violation ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Les utilisateurs doivent être formés sur les actions à mener en cas de violation de la politique de sécurité.'),
  ('REG 28-8', 'Non-conformité à l’exigence REG 28-8 « Ne pas se connecter via des réseaux sans fil non sécurisés ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Éviter de se connecter au réseau de l''organisme par l''intermédiaire de réseaux sans fil non sécurisés.'),
  ('REG 8-8', 'Non-conformité à l’exigence REG 8-8 « Choix des équipements par l''ASSI selon analyse de risque ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Chaque ASSI doit choisir les techniques et les équipements appropriés sur la base des résultats d''une évaluation de risque physique et d''une analyse des coûts de contre-mesures ou des avantages associés.'),
  ('REG 7-8', 'Non-conformité à l’exigence REG 7-8 « Intégration de la sécurité dans la chaîne d''approvisionnement ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Les clauses contractuelles entre les fournisseurs et l''entité doivent intégrer toute la chaîne d''approvisionnement informatique : conformité avec les normes relatives à la sécurité des produits informatiques, publication des exigences de sécurité satisfaites par leurs produits et en fournir la preuve.'),
  ('REG 29-8', 'Non-conformité à l’exigence REG 29-8 « Formation à la détection des actions suspectes ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Les utilisateurs doivent être formés à la détection des actions suspectes ou anormales pouvant présager un incident lié à la sécurité des systèmes d''information (dysfonctionnements ou comportements anormaux du système d''information).'),
  ('REG 4-1', 'Non-conformité à l’exigence REG 4-1 « Programme de sensibilisation et formation SSI ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Un programme de sensibilisation et de formation à la sécurité des systèmes d''information doit être élaboré, revu et régulièrement mis à jour.'),
  ('REG 20-8', 'Non-conformité à l’exigence REG 20-8 « Audit régulier des procédures d''exploitation ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les procédures d''exploitation doivent être régulièrement auditées, contrôlées et mises à jour.'),
  ('REG 18-2', 'Non-conformité à l’exigence REG 18-2 « Contrôle des droits d''accès utilisateurs (lecture, écriture, suppression) ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les droits d''accès des utilisateurs doivent être contrôlés (lecture, écriture, suppression, …).'),
  ('REG 4-2', 'Non-conformité à l’exigence REG 4-2 « Cohérence du programme avec la politique de sécurité ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Ce programme doit être cohérent avec la politique de sécurité de l''organisme.'),
  ('REG 29-9', 'Non-conformité à l’exigence REG 29-9 « Procédure de réponse aux incidents documentée ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : La procédure de réponse aux incidents doit comprendre : une phase de recueil et d''analyse des preuves, une communication détaillée sur l''incident survenu, la méthode de traitement utilisée, etc.'),
  ('REG 21-1', 'Non-conformité à l’exigence REG 21-1 « Identification et consignation des changements significatifs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut identifier et consigner les changements significatifs.'),
  ('REG 18-3', 'Non-conformité à l’exigence REG 18-3 « Accès aux applications par mécanisme de connexion sécurisée ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut restreindre l''accès aux applications par un mécanisme de connexion sécurisée.'),
  ('REG 28-9', 'Non-conformité à l’exigence REG 28-9 « Mécanisme d''effacement à distance en cas de perte ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Mettre en place un mécanisme d''effacement des données, en cas de perte d''appareils mobiles.'),
  ('REG 7-9', 'Non-conformité à l’exigence REG 7-9 « Procédures d''audit des prestations fournisseurs ».', 'Manquement à une exigence PSSI-ES (Relation avec les fournisseurs) — risque porté par la chaîne de sous-traitance et les fournisseurs.', 'Mettre en œuvre l’exigence : Mettre en place des procédures d''audit sur les prestations effectuées par les fournisseurs ainsi que sur la qualité de ces services.'),
  ('REG 9-1', 'Non-conformité à l’exigence REG 9-1 « Entrée sur carte d''accès visiteur ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : L''entrée est autorisée sur présentation de la carte d''accès visiteur. L''identité du visiteur, le but de sa visite, l''heure d''entrée et de sortie doivent être inscrits dans un registre. Il faut authentifier l''identité du visiteur à l''aide d''un moyen approprié.'),
  ('REG 28-10', 'Non-conformité à l’exigence REG 28-10 « Contrôle des appareils mobiles tout au long de leur cycle de vie ».', 'Manquement à une exigence PSSI-ES (Cloud, appareils mobiles et télétravail) — fuite de données via le cloud, le mobile ou le télétravail.', 'Mettre en œuvre l’exigence : Procéder au contrôle des appareils mobiles durant tout leur cycle de vie.'),
  ('REG 29-10', 'Non-conformité à l’exigence REG 29-10 « Procédure de recueil des preuves numériques ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : La procédure relative au recueil de preuves doit prendre en compte la chaîne de traçabilité, les aptitudes et la sécurité du personnel, les fonctions et les responsabilités, la documentation et les séances d''information. Il faut appliquer la norme ISO/CEI 27037.'),
  ('REG 9-2', 'Non-conformité à l’exigence REG 9-2 « Visites hors heures de service interdites ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les visites ne sont pas autorisées en dehors des heures de service ou de pause.'),
  ('REG 21-2', 'Non-conformité à l’exigence REG 21-2 « Planification des changements et des tests ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut planifier les changements et la phase de test.'),
  ('REG 18-4', 'Non-conformité à l’exigence REG 18-4 « Authentification forte pour données classifiées ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Une technologie d''authentification forte doit être utilisée lorsque les données sont classifiées.'),
  ('REG 4-3', 'Non-conformité à l’exigence REG 4-3 « Adaptation aux niveaux de responsabilité ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Ce programme doit prendre en compte les différents niveaux de responsabilités des membres de l''organisme.'),
  ('REG 18-5', 'Non-conformité à l’exigence REG 18-5 « Limitation des tentatives de connexion non autorisées ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut limiter le nombre de connexions non autorisées aux applications.'),
  ('REG 29-11', 'Non-conformité à l’exigence REG 29-11 « Typologie des incidents et retours d''expérience ».', 'Manquement à une exigence PSSI-ES (Gestion des incidents) — détection et réponse aux incidents tardives ou inefficaces.', 'Mettre en œuvre l’exigence : Il faut déterminer la typologie des incidents de sécurité, et en tirer tous les enseignements nécessaires.'),
  ('REG 9-3', 'Non-conformité à l’exigence REG 9-3 « Port d''identification visible obligatoire ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les agents doivent porter un moyen d''identification visible ; ils doivent immédiatement aviser le personnel de sécurité s''ils rencontrent des visiteurs non accompagnés et toute personne ne portant pas d''identification visible (exemple : port de badge).'),
  ('REG 4-4', 'Non-conformité à l’exigence REG 4-4 « Mise à jour intégrant les retours d''expérience ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Ce programme doit être mis à jour régulièrement afin de prendre en compte les nouveaux agents et les enseignements tirés des incidents liés à la sécurité de l''information déjà survenus.'),
  ('REG 21-3', 'Non-conformité à l’exigence REG 21-3 « Évaluation de l''impact sécurité des changements ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut apprécier les incidences potentielles de ces changements sur la sécurité de l''information.'),
  ('REG 9-4', 'Non-conformité à l’exigence REG 9-4 « Accès salle de serveurs limité aux personnes autorisées ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : L''accès à la salle de serveurs doit être limité aux seules personnes autorisées.'),
  ('REG 18-6', 'Non-conformité à l’exigence REG 18-6 « Pas d''informations révélatrices lors d''une connexion échouée ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il ne faut pas afficher d''informations qui peuvent fournir des indications lors d''une tentative de connexion non autorisée.'),
  ('REG 4-5', 'Non-conformité à l’exigence REG 4-5 « Engagement visible de la direction ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Ce programme doit faire apparaître clairement l''engagement de la direction sur la problématique de la sécurité des systèmes d''information.'),
  ('REG 21-4', 'Non-conformité à l’exigence REG 21-4 « Procédure formelle d''autorisation des changements ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Une procédure d''autorisation formelle des changements proposés doit être mise en œuvre.'),
  ('REG 21-5', 'Non-conformité à l’exigence REG 21-5 « Vérification du respect des exigences de sécurité ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut vérifier que les exigences de sécurité de l''information sont respectées.'),
  ('REG 10-1', 'Non-conformité à l’exigence REG 10-1 « Équipements clés dans des emplacements non accessibles au public ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les équipements-clés doivent être installés dans un emplacement non accessible au public. Ils doivent être configurés de manière à empêcher toute fuite d''information sensible, notamment par rayonnement électromagnétique (mise en place de cages de faraday).'),
  ('REG 4-6', 'Non-conformité à l’exigence REG 4-6 « Formation continue et veille technologique ».', 'Manquement à une exigence PSSI-ES (Sécurité du personnel) — exposition liée à un personnel non sensibilisé ou non habilité.', 'Mettre en œuvre l’exigence : Un programme de formation continue doit être mis en place pour les agents chargés de veiller à l''application effective de la politique de sécurité, afin qu''ils soient informés sur les menaces et vulnérabilités les plus récentes (veille technologique).'),
  ('REG 18-7', 'Non-conformité à l’exigence REG 18-7 « Changement impératif des mots de passe par défaut ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les mots de passe par défaut doivent être changés impérativement.'),
  ('REG 21-6', 'Non-conformité à l’exigence REG 21-6 « Communication des changements aux personnes concernées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut transmettre les informations détaillées sur les changements apportés à toutes les personnes concernées.'),
  ('REG 18-8', 'Non-conformité à l’exigence REG 18-8 « Fermeture des sessions inactives et journalisation ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut mettre en place un système de contrôle des tentatives de connexion automatique et fermer les sessions inactives au bout d''un certain temps d''inactivité. Toutes les tentatives de connexion doivent être journalisées.'),
  ('REG 10-2', 'Non-conformité à l’exigence REG 10-2 « Répertoires internes non accessibles sans autorisation ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les répertoires et les annuaires téléphoniques internes, identifiant les emplacements des moyens de traitement de l''information sensible, ne doivent pas être facilement accessibles sans autorisation.'),
  ('REG 18-9', 'Non-conformité à l’exigence REG 18-9 « Mots de passe robustes, non transmis en clair ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les mots de passe doivent être robustes. Ils ne doivent pas être transmis en clair. Il faut les changer régulièrement suivant une périodicité définie.'),
  ('REG 21-7', 'Non-conformité à l’exigence REG 21-7 « Procédures de repli en cas d''échec ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut mettre en œuvre les procédures de repli, incluant les procédures et les responsabilités en cas d''abandon et de récupération, suite à l''échec des changements ou à des événements imprévus.'),
  ('REG 10-3', 'Non-conformité à l’exigence REG 10-3 « Discrétion des bâtiments ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les bâtiments doivent être discrets et ne donner que le minimum d''indications sur leur usage, sans signe évident identifiant la présence d''activités de traitement de l''information.'),
  ('REG 11-1', 'Non-conformité à l’exigence REG 11-1 « Accès sur la base du besoin d''en connaître ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Le personnel doit être informé de l''existence de zones sécurisées et qu''il n''y a accès que sur la seule base des principes du besoin d''en connaître et d''utiliser.'),
  ('REG 18-10', 'Non-conformité à l’exigence REG 18-10 « Interdiction d''installation de logiciels sans autorisation ASSI ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut prévenir rigoureusement et interdire formellement l''installation de logiciels sans l''autorisation de l''Agent de la Sécurité des Systèmes d''Information (ASSI).'),
  ('REG 21-8', 'Non-conformité à l’exigence REG 21-8 « Processus de modification d''urgence ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut mettre en place un processus de modification d''urgence permettant une mise en œuvre rapide et contrôlée des modifications requises par la résolution d''un incident.'),
  ('REG 22-1', 'Non-conformité à l’exigence REG 22-1 « Environnements distincts (dev, test, exploitation) ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut exécuter les logiciels de développement et les logiciels d''exploitation sur des systèmes informatiques différents et dans des domaines ou des répertoires différents.'),
  ('REG 11-2', 'Non-conformité à l’exigence REG 11-2 « Travail sans surveillance évité ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Le travail sans surveillance dans les zones sécurisées doit être évité pour des raisons de sécurité.'),
  ('REG 18-11', 'Non-conformité à l’exigence REG 18-11 « Désinstallation des applications non indispensables ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les applications ou utilitaires non indispensables doivent être désinstallées.'),
  ('REG 22-2', 'Non-conformité à l’exigence REG 22-2 « Tests en environnement de test avant production ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut tester les modifications à apporter aux systèmes et aux applications dans un environnement de test avant de les appliquer aux systèmes en exploitation.'),
  ('REG 18-12', 'Non-conformité à l’exigence REG 18-12 « Contrôle de l''accès au code source ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : L''accès au code source des applications doit être contrôlé afin d''en assurer l''intégrité.'),
  ('REG 11-3', 'Non-conformité à l’exigence REG 11-3 « Verrouillage des zones inoccupées ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les zones sécurisées inoccupées doivent être physiquement verrouillées et contrôlées périodiquement.'),
  ('REG 11-4', 'Non-conformité à l’exigence REG 11-4 « Interdiction d''équipements photo/vidéo/audio ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : L''utilisation d''équipements photo, vidéo, audio ou d''autres dispositifs tels que les caméras intégrées à des appareils mobiles, doit être interdite, sauf autorisation.'),
  ('REG 19-1', 'Non-conformité à l’exigence REG 19-1 « Politique d''accès réseau avec exigences d''authentification ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut mettre en place une politique d''accès aux réseaux de l''entité, qui précise les exigences d''authentification des utilisateurs.'),
  ('REG 22-3', 'Non-conformité à l’exigence REG 22-3 « Séparation des activités de développement et de test ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les activités de développement doivent être séparées des activités de test.'),
  ('REG 22-4', 'Non-conformité à l’exigence REG 22-4 « Outils de développement non accessibles depuis les systèmes en exploitation ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les compilateurs, les éditeurs et les autres outils de développement ou les utilitaires systèmes ne doivent pas être accessibles depuis les systèmes en exploitation, lorsqu''ils ne sont pas nécessaires.'),
  ('REG 19-2', 'Non-conformité à l’exigence REG 19-2 « Responsabilités et procédures de gestion des équipements réseau ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut définir les responsabilités et les procédures de gestion des équipements réseau.'),
  ('REG 12-1', 'Non-conformité à l’exigence REG 12-1 « Zone d''approvisionnement à accès restreint ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Désigner la zone d''approvisionnement pour les matières entrantes (accès restreint au personnel de livraison).'),
  ('REG 12-2', 'Non-conformité à l’exigence REG 12-2 « Inspection des matières entrantes ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Inspecter les matières entrantes, par des équipements appropriés, pour vérifier la présence éventuelle de substances dangereuses (explosives, chimiques, ou autres) avant qu''elles ne quittent la zone de livraison.'),
  ('REG 22-5', 'Non-conformité à l’exigence REG 22-5 « Profils différents pour exploitation et test ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les utilisateurs doivent utiliser des profils différents pour les systèmes en exploitation et les systèmes de test, et les menus doivent afficher les messages d''identification adéquats pour réduire le risque d''erreur.'),
  ('REG 19-3', 'Non-conformité à l’exigence REG 19-3 « Transmission conforme à la législation ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les moyens de transmission de l''information doivent être conformes à la législation en vigueur.'),
  ('REG 22-6', 'Non-conformité à l’exigence REG 22-6 « Interdiction de copier des données sensibles en test ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il ne faut pas copier de données sensibles dans l''environnement du système de test, à moins qu''il ne soit doté de mesures de sécurité équivalentes.'),
  ('REG 19-4', 'Non-conformité à l’exigence REG 19-4 « Surveillance et journalisation des activités réseau ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut mettre en place un mécanisme de surveillance et de journalisation de toutes les activités dans le réseau.'),
  ('REG 12-3', 'Non-conformité à l’exigence REG 12-3 « Enregistrement des matières dès l''arrivée ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Enregistrer les matières entrantes dès leur arrivée sur le site conformément aux procédures d''enregistrement des actifs.'),
  ('REG 19-5', 'Non-conformité à l’exigence REG 19-5 « Protection des données sur réseaux publics selon la classification ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les données transmises via les réseaux publics doivent être protégées selon leur niveau de classification. Il faut utiliser les réseaux de l''État, autant que faire se peut, pour transmettre des données hors de l''entité.'),
  ('REG 12-4', 'Non-conformité à l’exigence REG 12-4 « Comptabilité des équipements par les directions ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Toute la comptabilité matière doit être effectuée par les directions chargées des équipements dans les différentes entités.'),
  ('REG 23-1', 'Non-conformité à l’exigence REG 23-1 « Antivirus installé sur tous les postes et terminaux ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Un outil de protection contre les logiciels malveillants doit être installé sur tous les serveurs, les ordinateurs fixes et les terminaux mobiles.'),
  ('REG 13-1', 'Non-conformité à l’exigence REG 13-1 « Systèmes d''alarme périodiquement contrôlés ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les installations sensibles doivent être équipées de systèmes d''alarme périodiquement contrôlés.'),
  ('REG 19-6', 'Non-conformité à l’exigence REG 19-6 « Sécurisation des services réseau (authentification, chiffrement, non-répudiation) ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Les services de réseau doivent, en accord avec le fournisseur, être sécurisés par des fonctions de sécurité : l''authentification, l''intégrité, le chiffrement, la non-répudiation et les contrôles de connexion réseau.'),
  ('REG 23-2', 'Non-conformité à l’exigence REG 23-2 « Mise à jour régulière des outils de protection ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : L''utilisateur, ou à défaut, l''administrateur doit prendre toutes les mesures et effectuer les paramétrages nécessaires pour la mise à jour de l''outil de protection.'),
  ('REG 23-3', 'Non-conformité à l’exigence REG 23-3 « Logiciels de détection et réparation à jour ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut installer et mettre à jour régulièrement les logiciels de détection et de réparation pour analyser les ordinateurs et les supports.'),
  ('REG 13-2', 'Non-conformité à l’exigence REG 13-2 « Matériel en salles sécurisées, portes et fenêtres protégées ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tout le matériel doit être installé dans des salles sécurisées. Les portes et les fenêtres ne doivent pas être des moyens d''accès ou de connexion au matériel, de l''extérieur de la zone sécurisée. Des issues de secours doivent être prévues dans tous les sites.'),
  ('REG 19-7', 'Non-conformité à l’exigence REG 19-7 « Analyse de risques pour les réseaux sans fil ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Le déploiement de réseaux sans fil doit faire l''objet d''une analyse de risques spécifiques. Des mesures complémentaires doivent être prises dans le cadre de la défense en profondeur. En particulier, une segmentation du réseau doit être mise en place.'),
  ('REG 23-4', 'Non-conformité à l’exigence REG 23-4 « Alerte diffusée en cas de détection de malware ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : En cas de détection de logiciels malveillants, une alerte doit être diffusée dans l''ensemble de l''entité.'),
  ('REG 13-3', 'Non-conformité à l’exigence REG 13-3 « Détection et lutte contre l''incendie ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Dans tous les sites sensibles, des dispositifs de détection et de lutte contre l''incendie tels que les détecteurs de fumée et les extincteurs, doivent être installés, contrôlés et testés régulièrement.'),
  ('REG 19-8', 'Non-conformité à l’exigence REG 19-8 « Cloisonnement physique et/ou logique des réseaux ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut effectuer un cloisonnement, physique et/ou logique des réseaux informatiques, suivant un critère bien défini pour séparer les réseaux : par service administratif, par niveau de sécurité, etc.'),
  ('REG 13-4', 'Non-conformité à l’exigence REG 13-4 « Sites en briques réfractaires, sans matériel inflammable ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les sites sensibles doivent être en briques réfractaires et ne doivent contenir aucun matériel inflammable tel que des meubles en bois, des rideaux ou des tapis.'),
  ('REG 19-9-1', 'Non-conformité à l’exigence REG 19-9-1 « Algorithmes de chiffrement labellisés par la Commission nationale de cryptologie ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut choisir des algorithmes de chiffrement labellisés par la Commission nationale de cryptologie.'),
  ('REG 23-5', 'Non-conformité à l’exigence REG 23-5 « Ne pas ouvrir les courriers électroniques suspects ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les courriers électroniques suspects, avec ou sans pièces jointes, ne doivent pas être ouverts.'),
  ('REG 13-5', 'Non-conformité à l’exigence REG 13-5 « Conformité des installations électriques ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Il faut utiliser les spécifications techniques des fabricants des matériels électriques et se conformer aux normes de sécurité électrique des sociétés locales prestataires d''électricité pour empêcher les incendies.'),
  ('REG 23-6', 'Non-conformité à l’exigence REG 23-6 « Anti-spams et listes noires sur les serveurs de messagerie ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Des anti-spams doivent être installés sur les serveurs de messagerie. Des listes noires en temps réel doivent être utilisées pour bloquer les spams.'),
  ('REG 19-9-5', 'Non-conformité à l’exigence REG 19-9-5 « Authentification forte et chiffrement de la messagerie ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut mettre en place un système d''authentification forte et un système de chiffrement pour sécuriser la messagerie électronique de l''entité.'),
  ('REG 13-6', 'Non-conformité à l’exigence REG 13-6 « Inspection et test régulier des installations électriques ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Il faut faire inspecter et tester régulièrement les installations électriques pour s''assurer de leur bon fonctionnement (systèmes d''éclairage, interrupteurs, câbles électriques, générateur de secours, …).'),
  ('REG 19-9-7', 'Non-conformité à l’exigence REG 19-9-7 « Chiffrement des disques contenant des informations sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Chiffrer une ou plusieurs parties des disques durs des systèmes d''information contenant les informations sensibles.'),
  ('REG 23-7', 'Non-conformité à l’exigence REG 23-7 « Filtres de contenu web installés ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Des filtres de contenus doivent être installés pour empêcher l''utilisation de sites web malveillants ou suspectés en tant que tels.'),
  ('REG 13-7', 'Non-conformité à l’exigence REG 13-7 « Alimentation électrique d''urgence par générateur de secours ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Une alimentation électrique d''urgence doit être sauvegardée par un générateur de secours.'),
  ('REG 19-9-11', 'Non-conformité à l’exigence REG 19-9-11 « Longueurs de clés conformes aux recommandations ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut choisir des longueurs de clefs de chiffrement conformes aux recommandations de la Commission nationale de cryptologie.'),
  ('REG 23-8', 'Non-conformité à l’exigence REG 23-8 « Procédures de continuité post-attaque ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Établir des procédures de continuité d''activités de l''organisme, après une attaque par logiciels malveillants, comprenant les sauvegardes de tous les logiciels et données nécessaires ainsi que les dispositions de sauvegarde.'),
  ('REG 19-9-12', 'Non-conformité à l’exigence REG 19-9-12 « Politique rigoureuse de gestion des clés de chiffrement ».', 'Manquement à une exigence PSSI-ES (Sécurité logique) — accès illégitime ou compromission logique du système d’information.', 'Mettre en œuvre l’exigence : Il faut mettre en œuvre une politique rigoureuse de gestion des clefs de chiffrement afin d''en assurer la protection, sans faille, durant tout leur cycle de vie.'),
  ('REG 13-8', 'Non-conformité à l’exigence REG 13-8 « Alimentation électrique permanente pour équipements sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les équipements sensibles doivent disposer d''une alimentation électrique permanente.'),
  ('REG 23-9', 'Non-conformité à l’exigence REG 23-9 « Vigilance lors de la maintenance et du dépannage ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les utilisateurs doivent veiller à se protéger de l''introduction de logiciels malveillants qui peuvent contourner les mesures de protection habituelles, lors des opérations de maintenance et de dépannage.'),
  ('REG 23-10', 'Non-conformité à l’exigence REG 23-10 « Bulletins d''alerte vérifiés de sources qualifiées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut s''assurer que les bulletins d''alerte concernant les logiciels malveillants sont exacts et informatifs, et proviennent de sources qualifiées et réputées (publications réputées, sites internet fiables, éditeurs de logiciels contre les logiciels malveillants).'),
  ('REG 13-9', 'Non-conformité à l’exigence REG 13-9 « Matériel sur support surélevé avec détection de fuite d''eau ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Le matériel doit être installé sur un support surélevé. Des systèmes de détection de fuite d''eau doivent être installés dans les sites sensibles.'),
  ('REG 13-10', 'Non-conformité à l’exigence REG 13-10 « Climatisation, ventilation et humidité contrôlées ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Des systèmes de climatisation, de ventilation, d''alimentation en gaz et d''évacuation des eaux usées doivent être installés, entretenus et vérifiés régulièrement pour empêcher d''éventuels endommagements des actifs et l''interruption des activités de l''entité. Des appareils de mesure de l''humidité et de la température doivent être prévus.'),
  ('REG 24-1', 'Non-conformité à l’exigence REG 24-1 « Sauvegarde périodique des données et configurations ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les données des utilisateurs, les configurations, les fichiers système et les messages électroniques doivent être périodiquement sauvegardés dans des serveurs dédiés, sur site et/ou hors site ou dans des supports de stockage amovibles.'),
  ('REG 24-3', 'Non-conformité à l’exigence REG 24-3 « Interdiction du stockage en ligne gratuit ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Le stockage en ligne gratuit, offert par certains prestataires privés, doit être interdit.'),
  ('REG 13-11', 'Non-conformité à l’exigence REG 13-11 « Sites de reprise à distance du site principal ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les sites de reprise sur sinistre et de stockage de données doivent être installés à des endroits très éloignés du site principal.'),
  ('REG 24-4', 'Non-conformité à l’exigence REG 24-4 « Chiffrement des sauvegardes sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut protéger les données sensibles sauvegardées en les chiffrant avec des moyens de chiffrement labellisés par la Commission nationale de cryptologie.'),
  ('REG 13-12', 'Non-conformité à l’exigence REG 13-12 « Stockage sécurisé des matériels défectueux ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Le matériel ou le support de stockage défectueux et les pièces de rechange, mis au rebut, doivent être stockés dans une pièce séparée qui doit être en permanence verrouillée.'),
  ('REG 13-13', 'Non-conformité à l’exigence REG 13-13 « Racks et baies sans signe descriptif ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : La salle d''équipements et les racks ne doivent comporter aucun signe écrit décrivant leurs noms, leurs buts, les diagrammes de réseau, les numéros de ports, les adresses IP, etc.'),
  ('REG 24-5', 'Non-conformité à l’exigence REG 24-5 « Sécurisation des locaux de stockage des sauvegardes ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les locaux de stockage des données sensibles doivent être sécurisés.'),
  ('REG 24-7', 'Non-conformité à l’exigence REG 24-7 « Test périodique de restauration des sauvegardes ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Un test de restauration doit être effectué périodiquement pour vérifier l''intégrité des données sauvegardées. La fréquence de ces tests doit être proportionnelle au degré de sensibilité des systèmes.'),
  ('REG 13-14', 'Non-conformité à l’exigence REG 13-14 « Nettoyage régulier des équipements ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les équipements doivent être nettoyés régulièrement pour éviter notamment la poussière.'),
  ('REG 25-1', 'Non-conformité à l’exigence REG 25-1 « Journaux d''événements complets ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les journaux d''événements doivent contenir : identifiants des utilisateurs, activités du système, date/heure des événements significatifs, identité ou emplacement du terminal, enregistrements des tentatives d''accès, modifications de configuration, utilisation des privilèges.'),
  ('REG 13-15', 'Non-conformité à l’exigence REG 13-15 « Interdiction d''activités non prévues dans les salles sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Il doit être strictement interdit d''effectuer des activités autres que celles prévues dans les salles abritant des équipements sensibles.'),
  ('REG 13-16', 'Non-conformité à l’exigence REG 13-16 « Interdiction de manger, boire et fumer ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Il doit être strictement interdit de manger, de boire et de fumer à l''intérieur de la zone sécurisée.'),
  ('REG 25-2', 'Non-conformité à l’exigence REG 25-2 « Protection des journaux contre la falsification ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les moyens de journalisation et l''information journalisée doivent être protégés contre les risques de falsification et les risques d''accès non autorisés.'),
  ('REG 25-3', 'Non-conformité à l’exigence REG 25-3 « Analyse automatique des journaux ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les fichiers de journalisation doivent être analysés par des outils automatiques destinés à cet effet.'),
  ('REG 14-1', 'Non-conformité à l’exigence REG 14-1 « Câbles enterrés autant que possible ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les lignes électriques et les lignes de télécommunication branchées aux systèmes d''information doivent être enterrées autant que faire se peut, par mesure de sécurité.'),
  ('REG 14-2', 'Non-conformité à l’exigence REG 14-2 « Séparation câbles électriques et télécommunication ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les câbles électriques doivent être séparés des câbles de télécommunication pour empêcher les interférences.'),
  ('REG 25-4', 'Non-conformité à l’exigence REG 25-4 « Journalisation des activités administrateurs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Il faut journaliser les activités de l''administrateur système et les activités de l''opérateur système, protéger et revoir régulièrement les journaux.'),
  ('REG 14-3', 'Non-conformité à l’exigence REG 14-3 « Câbles de télécommunication fiables dans des conduits ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les câbles de télécommunication doivent être fiables et installés dans des conduits. Des câbles redondants doivent être installés pour assurer une reprise rapide des services.'),
  ('REG 25-5', 'Non-conformité à l’exigence REG 25-5 « Système de détection des intrusions (IDS) ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Un système de détection des intrusions hors du contrôle des administrateurs système et réseau doit être utilisé pour vérifier la conformité des activités d''administration système et réseau.'),
  ('REG 25-6', 'Non-conformité à l’exigence REG 25-6 « Vérification permanente des journaux ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les journaux doivent être vérifiés de façon permanente.'),
  ('REG 14-4', 'Non-conformité à l’exigence REG 14-4 « Câbles électriques dans des conduits appropriés ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les câbles électriques doivent être installés dans des conduits appropriés.'),
  ('REG 25-7', 'Non-conformité à l’exigence REG 25-7 « Journalisation de tous les événements majeurs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Tous les événements majeurs doivent être enregistrés sur n''importe quel ordinateur ou système manipulant des données sensibles.'),
  ('REG 14-5', 'Non-conformité à l’exigence REG 14-5 « Panneaux de brassage et chambres de câblage isolés ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les panneaux de brassage et les salles des câbles doivent être isolés des zones d''accueil du public avec un accès contrôlé.'),
  ('REG 14-6', 'Non-conformité à l’exigence REG 14-6 « Panneaux de répartition électrique à accès limité ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les panneaux de répartition électrique ainsi que les chambres de câblage doivent être strictement contrôlés et l''accès limité au personnel autorisé.'),
  ('REG 26-1', 'Non-conformité à l’exigence REG 26-1 « Synchronisation NTP centralisée ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Toutes les horloges système, les horloges des ordinateurs et des périphériques réseau doivent être synchronisées à un serveur de temps central.'),
  ('REG 26-2', 'Non-conformité à l’exigence REG 26-2 « Serveur de temps de secours ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Le serveur de temps doit être doublé d''un serveur de secours installé dans un endroit sécurisé.'),
  ('REG 14-7', 'Non-conformité à l’exigence REG 14-7 « Paratonnerre et parafoudres sur sites sensibles ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Tous les sites sensibles doivent être équipés de paratonnerres et de parafoudres pour protéger respectivement les bâtiments et les matériels.'),
  ('REG 15-1', 'Non-conformité à l’exigence REG 15-1 « Maintenance par personnel autorisé uniquement ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Seul le personnel autorisé doit effectuer le service de maintenance.'),
  ('REG 26-3', 'Non-conformité à l’exigence REG 26-3 « Interdiction de modifier l''heure par les utilisateurs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les utilisateurs ne doivent pas être en mesure de changer la date, les paramètres du fuseau horaire ainsi que les paramètres de synchronisation du temps ou de l''horloge du système.'),
  ('REG 15-2', 'Non-conformité à l’exigence REG 15-2 « Contrat de maintenance avec fournisseurs accrédités ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les unités de maintenance doivent établir un contrat avec les fournisseurs accrédités, immédiatement après la mise en service du matériel.'),
  ('REG 27-1', 'Non-conformité à l’exigence REG 27-1 « Mise à jour par administrateurs qualifiés après autorisation ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : La mise à jour des logiciels en exploitation, des applications et des programmes doit être effectuée par des administrateurs qualifiés après autorisation du responsable de l''entité ou de l''AQSSI.'),
  ('REG 27-2', 'Non-conformité à l’exigence REG 27-2 « Correctifs recommandés par les éditeurs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les correctifs doivent être recommandés par les administrateurs système ou par les éditeurs du logiciel.'),
  ('REG 15-3', 'Non-conformité à l’exigence REG 15-3 « Clauses contractuelles de qualité et disponibilité ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les clauses du contrat doivent tenir compte des intérêts de l''organisme : qualité de service, disponibilité, temps de réponse, politiques de rechange, modalités de paiement. Le responsable de l''entité doit approuver le contrat.'),
  ('REG 27-3', 'Non-conformité à l’exigence REG 27-3 « Test des correctifs avant mise en production ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les correctifs doivent être appliqués sur un site de test, et si aucune anomalie n''est constatée, ils sont appliqués sur le site de production. Les correctifs critiques doivent avoir une haute priorité et être immédiatement installés.'),
  ('REG 15-4', 'Non-conformité à l’exigence REG 15-4 « Registre de maintenance ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les unités de maintenance doivent ouvrir un registre pour la traçabilité de leur travail, des paiements effectués, de la qualité, de la performance et de l''expiration du contrat.'),
  ('REG 15-5', 'Non-conformité à l’exigence REG 15-5 « Approbation du travail fournisseur par les administrateurs ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Le travail effectué par les fournisseurs doit être approuvé, notamment par les administrateurs systèmes, réseaux et de bases de données ; ils doivent tenir un registre à ce sujet.'),
  ('REG 27-5', 'Non-conformité à l’exigence REG 27-5 « Sauvegarde complète avant l''application d''un correctif ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Une sauvegarde complète doit être effectuée avant l''application d''un correctif.'),
  ('REG 27-7', 'Non-conformité à l’exigence REG 27-7 « Téléchargement automatique des mises à jour recommandées ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les ordinateurs connectés à internet doivent être configurés pour télécharger automatiquement les mises à jour recommandées. Les ordinateurs non connectés doivent être mis à jour manuellement.'),
  ('REG 15-6', 'Non-conformité à l’exigence REG 15-6 « Surveillance étroite des activités de maintenance ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les activités de maintenance doivent être effectuées sous une surveillance étroite et adéquate des ASSI. En cas d''intervention d''un prestataire, les ASSI doivent toujours être présents et veiller à ce qu''aucun fichier ou programme de données ne soit copié.'),
  ('REG 15-7', 'Non-conformité à l’exigence REG 15-7 « Conservation des dossiers de maintenance ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les dossiers de maintenance doivent être conservés pour suivi.'),
  ('REG 27-8', 'Non-conformité à l’exigence REG 27-8 « Journalisation des mises à jour et correctifs ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Les mises à jour, mises à niveau et correctifs doivent être journalisés par l''administrateur système dans un registre.'),
  ('REG 27-9', 'Non-conformité à l’exigence REG 27-9 « Restauration en cas d''impact négatif ».', 'Manquement à une exigence PSSI-ES (Sécurité de l’exploitation) — indisponibilité ou compromission en exploitation courante.', 'Mettre en œuvre l’exigence : Si l''application automatique d''un correctif ou d''une mise à jour affecte négativement les systèmes, il faut rétablir les systèmes originaux à partir des sauvegardes.'),
  ('REG 15-8', 'Non-conformité à l’exigence REG 15-8 « Sauvegarde des données avant remise en réparation ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : En cas de remise d''un équipement pour réparation, les données qui y sont contenues doivent être sauvegardées dans d''autres supports et être supprimées de manière sécurisée.'),
  ('REG 16-1', 'Non-conformité à l’exigence REG 16-1 « Supports amovibles sensibles en coffre ou armoire ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les supports amovibles de stockage de données sensibles (disques durs, disquettes, bandes magnétiques, CDROM, DVD, Blu-ray, clés USB, cartes SD, cartes à puces …) doivent être conservés dans un coffre ou une armoire au même titre que les documents et correspondances sensibles sur support papier.'),
  ('REG 16-2', 'Non-conformité à l’exigence REG 16-2 « Clés des locaux en endroit sûr hors heures de travail ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Après les heures de travail ou en l''absence des utilisateurs, les clefs des locaux, des coffres et des armoires doivent être gardées dans un endroit sûr accessible aux seules personnes autorisées.'),
  ('REG 16-3', 'Non-conformité à l’exigence REG 16-3 « Effacement logique et physique des fichiers classifiés périmés ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les fichiers contenant des informations classifiées et qui sont périmées doivent être effacés. Cette destruction ne doit pas être uniquement logique mais doit être accompagnée d''un effacement physique pour prévenir toute possibilité de lecture.'),
  ('REG 16-4', 'Non-conformité à l’exigence REG 16-4 « Retrait immédiat des documents sensibles des imprimantes ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Les documents contenant des informations sensibles ou classifiées doivent être immédiatement retirés des imprimantes, des photocopieuses, des scanneurs, des appareils de télécopie après leur utilisation.'),
  ('REG 16-5', 'Non-conformité à l’exigence REG 16-5 « Verrouillage automatique des postes en absence ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : En l''absence de leurs utilisateurs, les ordinateurs et les terminaux doivent être déconnectés ou protégés par un verrouillage automatique (délai court) de l''écran ou du clavier contrôlé par un mot de passe ou un autre mécanisme d''authentification.'),
  ('REG 16-6', 'Non-conformité à l’exigence REG 16-6 « Interdiction de reproduction non autorisée ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : L''utilisation non autorisée des photocopieurs et autres appareils de reproduction (par exemple les scanneurs ou les appareils photo numériques) doit être strictement interdite.'),
  ('REG 16-7', 'Non-conformité à l’exigence REG 16-7 « Impression sécurisée par identification ».', 'Manquement à une exigence PSSI-ES (Sécurité physique) — intrusion ou sinistre physique sur les installations sensibles.', 'Mettre en œuvre l’exigence : Il faut utiliser des imprimantes dotées d''une fonction d''identification par code personnel, afin que seules les personnes ayant initié une tâche d''impression puissent récupérer leurs documents imprimés et uniquement lorsqu''elles se trouvent à proximité de l''imprimante.')
) as t(code, descr, risk, reco)
join public.controls c on c.code = t.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000017')
where not exists (
  select 1 from public.finding_templates ft
  where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc'
);
